def main():
    target = ROOT / "research/industry-food-agprocessing-evidence.csv"
    with target.open("w", newline="", encoding="utf-8") as handle:
        writer = csv.DictWriter(handle, fieldnames=FIELDS)
        writer.writeheader()
        writer.writerows(ROWS)
    envelope = {"schema_version": "1.0", "research_cutoff": "2026-10-22", "purpose": "Future-reference research knowledge; no causal or risk ranking inferred", "record_grain": "One scoped claim/analysis or source definition, not one independent study", "blank_semantics": "Not extracted or not applicable; never a zero effect", "records": ROWS}
    target.with_suffix(".json").write_text(json.dumps(envelope, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    print(json.dumps({"records": len(ROWS), "unique_claim_ids": len({row['claim_id'] for row in ROWS}), "csv": str(target), "csv_sha256": hashlib.sha256(target.read_bytes()).hexdigest()}, indent=2))


if __name__ == "__main__":
    main()
